svg.script:
(function () {
  var root = document.getElementById('confFlow');
  var step = 0;
  var busy = false;
  var DURATION = { 0: 700, 1: 1000, 2: 1200, 3: 1700, 4: 1000 };

  function play(next) {
    busy = true;
    step = next;
    root.setAttribute('data-step', String(next));
    root.setAttribute('data-anim', '1');
    window.setTimeout(function () {
      root.removeAttribute('data-anim');
      busy = false;
    }, DURATION[next]);
  }

  root.addEventListener('click', function () {
    if (busy) {
      return;
    }
    play((step + 1) % 5);
  });
})();
